def int_to_mini_roman(number):
    """
    Given a positive integer or a string representing a positive integer,
    convert it to its Roman numeral equivalent as a lowercase string.
    If the input is an integer less than 20, return it as is (int).
    If the input is a string representing a number (<= 1000),
    return its Roman numeral in lowercase.

    Restrictions:
    - Number (int) must be between 1 and 1000 inclusive.
    - String input length <= 4 and numeric, representing a number <= 1000.

    Examples:
    >>> int_to_mini_roman(19) == 19
    True
    >>> int_to_mini_roman('152') == 'clii'
    True
    >>> int_to_mini_roman(426) == 'cdxxvi'
    True
    """
    # Mapping Roman numerals for digits in each place value
    # Index corresponds to digit 0-9, value is the Roman numeral part for that digit
    thousands = ["", "m"]
    hundreds = ["", "c", "cc", "ccc", "cd", "d", "dc", "dcc", "dccc", "cm"]
    tens = ["", "x", "xx", "xxx", "xl", "l", "lx", "lxx", "lxxx", "xc"]
    ones = ["", "i", "ii", "iii", "iv", "v", "vi", "vii", "viii", "ix"]

    def to_roman(num):
        # num is int between 1 and 1000
        t = thousands[num // 1000]
        h = hundreds[(num % 1000) // 100]
        te = tens[(num % 100) // 10]
        o = ones[num % 10]
        return (t + h + te + o).lower()

    # Handle input type and restrictions
    if isinstance(number, int):
        if not (1 <= number <= 1000):
            raise ValueError("Integer input must be between 1 and 1000 inclusive.")
        # If number < 20, return int as is (according to examples)
        if number < 20:
            return number
        else:
            return to_roman(number)
    elif isinstance(number, str):
        if not number.isdigit():
            raise ValueError("String input must be numeric.")
        if len(number) > 4:
            raise ValueError("String input length must be <= 4.")
        num = int(number)
        if not (1 <= num <= 1000):
            raise ValueError("String numeric value must be between 1 and 1000 inclusive.")
        # For string input, always return Roman numeral string (lowercase)
        return to_roman(num)
    else:
        raise TypeError("Input must be either int or str.")


