def all_prefixes(value: Union[str, int]) -> Tuple[List[str], Tuple[int, ...]]:
    """
    Returns a list of all prefixes from shortest to longest of the input string or integer (converted to string),
    along with a tuple of the length of each prefix respectively.
    The function uses recursion and does not use any loops.

    >>> all_prefixes('abc')
    (['a', 'ab', 'abc'], (1, 2, 3))
    >>> all_prefixes(123)
    (['1', '12', '123'], (1, 2, 3))
    """
    s = str(value)

    def helper(i: int) -> Tuple[List[str], Tuple[int, ...]]:
        if i == 0:
            return ([], ())
        prefixes, lengths = helper(i - 1)
        prefix = s[:i]
        return (prefixes + [prefix], lengths + (i,))

    return helper(len(s))


