def check_dict_case(d):
    """
    Given a dictionary, return an integer if all keys are strings in lower 
    case or return a string if all keys are strings in upper case, else return False.
    The function should return a string 'Empty' if the given dictionary is empty.
    Do not use loops or any other iterative functions in the implementation.
    The time complexity of the function should be O(1).
    The function should also work for numeric dictionaries and return an integer if all keys are even numbers.
    The function only supports dictionaries with up to 3 keys, else returns False.

    Examples:
    check_dict_case({"a":"apple", "b":"banana"}) -> 1
    check_dict_case({"a":"apple", "A":"banana", "B":"banana"}) -> False
    check_dict_case({"a":"apple", 8:"banana", "a":"apple"}) -> False
    check_dict_case({"Name":"John", "Age":"36", "City":"Houston"}) -> False
    check_dict_case({"STATE":"NC", "ZIP":"12345" }) -> 'UPPERCASE'
    check_dict_case({2:"apple", 4:"banana"}) -> 2
    """

    keys = tuple(d.keys())
    n = len(keys)

    if n == 0:
        return 'Empty'
    if n > 3:
        return False

    # Helper functions without loops
    def all_lower_str(k):
        # Returns True if k is a string and all lowercase
        return isinstance(k, str) and k.islower()

    def all_upper_str(k):
        # Returns True if k is a string and all uppercase
        return isinstance(k, str) and k.isupper()

    def all_even_num(k):
        # Returns True if k is int and even
        return isinstance(k, int) and (k % 2 == 0)

    # Check all keys for lower case strings
    if n == 1:
        if all_lower_str(keys[0]):
            return 1
        if all_upper_str(keys[0]):
            return 'UPPERCASE'
        if all_even_num(keys[0]):
            return keys[0]
        return False
    elif n == 2:
        if all_lower_str(keys[0]) and all_lower_str(keys[1]):
            return 1
        if all_upper_str(keys[0]) and all_upper_str(keys[1]):
            return 'UPPERCASE'
        if all_even_num(keys[0]) and all_even_num(keys[1]):
            return keys[0]
        return False
    else:  # n == 3
        if all_lower_str(keys[0]) and all_lower_str(keys[1]) and all_lower_str(keys[2]):
            return 1
        if all_upper_str(keys[0]) and all_upper_str(keys[1]) and all_upper_str(keys[2]):
            return 'UPPERCASE'
        if all_even_num(keys[0]) and all_even_num(keys[1]) and all_even_num(keys[2]):
            return keys[0]
        return False


