def last_Digit_Factorial(n):
    """
    Returns the last digit of n!
    """
    if n == 0 or n == 1:
        return 1
    # For n >= 5, factorial ends with 0, so last digit is 0
    if n >= 5:
        return 0
    # For n < 5, compute factorial and return last digit
    fact = 1
    for i in range(2, n + 1):
        fact *= i
    return fact % 10

